function validate([nums, queries]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => v < 0 || v > 1000000000)) return 'Each value in nums is between 0 and 10^9.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 queries.';
  for (const query of queries) {
    if (query.length !== 3) return 'Each query has exactly three numbers.';
    const [type, a, b] = query;
    if (type === 1) {
      if (a < 0 || a >= n) return 'An update index must be a position of nums.';
      if (b < 0 || b > 1000000000) return 'An update value is between 0 and 10^9.';
    } else if (type === 2 || type === 3) {
      if (a < 0 || a > b || b >= n) return 'A range query or reversal needs 0 <= left <= right < nums.length.';
    } else {
      return 'Each query type is 1, 2 or 3.';
    }
  }
  return null;
}

