function getResults(nums, queries) {
  const sizeOf = node => (node === null ? 0 : node.size);
  const xorOf = node => (node === null ? 0 : node.total);
  function refresh(node) {
    node.size = sizeOf(node.left) + 1 + sizeOf(node.right);
    node.total = xorOf(node.left) ^ node.value ^ xorOf(node.right);
  }
  function pushDown(node) {
    if (node.flipped) {
      [node.left, node.right] = [node.right, node.left];
      if (node.left !== null) node.left.flipped = !node.left.flipped;
      if (node.right !== null) node.right.flipped = !node.right.flipped;
      node.flipped = false;
    }
  }
  // Cut a tree into its first count elements (front) and the rest (back).
  function split(node, count) {
    if (node === null) return [null, null];
    pushDown(node);
    if (sizeOf(node.left) >= count) {
      const [front, back] = split(node.left, count);
      node.left = back;
      refresh(node);
      return [front, node];
    }
    const [front, back] = split(node.right, count - sizeOf(node.left) - 1);
    node.right = front;
    refresh(node);
    return [node, back];
  }
  // Join two trees, keeping every element of front before every element of back.
  function merge(front, back) {
    if (front === null || back === null) return front ?? back;
    if (front.priority > back.priority) {
      pushDown(front);
      front.right = merge(front.right, back);
      refresh(front);
      return front;
    }
    pushDown(back);
    back.left = merge(front, back.left);
    refresh(back);
    return back;
  }
  let root = null;
  for (const value of nums) {
    const node = { value, total: value, size: 1, priority: Math.random(), left: null, right: null, flipped: false };
    root = merge(root, node);
  }
  const answer = [];
  for (const query of queries) {
    const [type, left] = query;
    const right = type === 1 ? left : query[2];
    const [before, rest] = split(root, left);
    const [middle, after] = split(rest, right - left + 1);
    if (type === 1) {
      middle.value = query[2];
      middle.total = query[2];
    } else if (type === 2) {
      answer.push(middle.total);
    } else {
      middle.flipped = !middle.flipped;
    }
    root = merge(merge(before, middle), after);
  }
  return answer;
}

