function getResults(nums, queries) {
  // Replay every query on a plain copy of the array.
  const array = nums.slice();
  const answer = [];
  for (const [type, a, b] of queries) {
    if (type === 1) {
      array[a] = b;
    } else if (type === 2) {
      let xor = 0;
      for (let i = a; i <= b; i++) xor ^= array[i];
      answer.push(xor);
    } else {
      const piece = array.slice(a, b + 1).reverse();
      for (let i = a; i <= b; i++) array[i] = piece[i - a];
    }
  }
  return answer;
}

