function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const q = large ? 2000 : 1 + Math.floor(rand() * 10);
  // Small inputs usually use tiny values so equal values and zero XORs show up.
  const top = large || rand() < 0.3 ? 1000000000 : 15;
  const pickValue = () => Math.floor(rand() * (top + 1));
  const nums = Array.from({ length: n }, pickValue);
  const queries = [];
  for (let i = 0; i < q; i++) {
    const type = 1 + Math.floor(rand() * 3);
    if (type === 1) {
      queries.push([1, Math.floor(rand() * n), pickValue()]);
    } else {
      const a = Math.floor(rand() * n);
      const b = Math.floor(rand() * n);
      queries.push([type, Math.min(a, b), Math.max(a, b)]);
    }
  }
  return [nums, queries];
}
